const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const d = items[i].json;
  const lang = String(d.language || 'Russian');
  const nm = String(d.name || '').trim();
  const system = 'Ты — заботливый персональный фитнес-тренер. Клиент' + (nm ? (' по имени ' + nm) : '') + ' несколько дней не выходил на связь. Напиши ему короткое тёплое сообщение-возвращение: по-доброму спроси, как он, всё ли в порядке с тренировками и самочувствием, и мягко пригласи продолжить (написать, если нужна корректировка плана, разбор питания или просто свериться). ПИШИ СТРОГО НА ЯЗЫКЕ: ' + lang + '. Без давления и упрёков за отсутствие. 2-4 строки, можно эмодзи. Обращайся прямо к клиенту, без вступлений вроде «вот сообщение».';
  const user = nm ? ('Имя клиента: ' + nm) : 'Клиент (имя неизвестно).';
  const payload = { model: 'claude-haiku-4-5-20251001', max_tokens: 300, system: system, messages: [{ role: 'user', content: user }] };
  out.push({ json: { bot_id: d.bot_id, user_id: d.user_id, chat_id: d.chat_id, bot_token: d.bot_token, payload: payload }, pairedItem: { item: i } });
}
return out;

const inp = $input.all();
const prompts = $('Промпт').all();
const out = [];
for (let i = 0; i < inp.length; i++) {
  const r = inp[i].json; const p = prompts[i].json;
  let text = '';
  try { text = r.content[0].text; } catch (e) { text = ''; }
  text = String(text || '').trim();
  if (!text) continue;
  out.push({ json: { bot_id: p.bot_id, user_id: p.user_id, chat_id: p.chat_id, bot_token: p.bot_token, text: text }, pairedItem: { item: i } });
}
return out;
